function money(p){return p.price==null?"Price on request":"RM "+Number(p.price).toFixed(2)}

function ensureImageViewer(){let viewer=document.getElementById("productImageViewer");if(viewer)return viewer;viewer=document.createElement("div");viewer.id="productImageViewer";viewer.className="image-viewer";viewer.hidden=true;viewer.innerHTML='<div class="image-viewer-panel" role="dialog" aria-modal="true" aria-label="Product image preview"><button class="image-viewer-close" type="button" aria-label="Close image preview">×</button><img class="image-viewer-full" alt=""><div class="image-viewer-actions"><a class="image-viewer-download" href="#" target="_blank" rel="noopener">⬇ Download / Save Image</a><span class="image-viewer-hint">If the image opens in a new tab, press and hold it and choose Download image / Save image.</span></div></div>';document.body.appendChild(viewer);const close=()=>{viewer.hidden=true;document.body.classList.remove("viewer-open")};viewer.addEventListener("click",e=>{if(e.target===viewer)close()});viewer.querySelector(".image-viewer-close").addEventListener("click",close);document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!viewer.hidden)close()});viewer._close=close;return viewer}
function openProductImage(url,label){const viewer=ensureImageViewer();viewer.querySelector(".image-viewer-full").src=url;viewer.querySelector(".image-viewer-full").alt=label+" — enlarged product image";const link=viewer.querySelector(".image-viewer-download");link.href=url;link.download=(label||"jersey-design").toLowerCase().replace(/[^a-z0-9]+/g,"-")+".webp";link.onclick=async function(e){e.preventDefault();let fallbackTab=window.open(url,"_blank");if(fallbackTab)fallbackTab.opener=null;try{const response=await fetch(url,{mode:"cors",cache:"no-store"});if(!response.ok)throw new Error("Image download unavailable");const blob=await response.blob();const objectUrl=URL.createObjectURL(blob);const a=document.createElement("a");a.href=objectUrl;a.download=link.download;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectUrl),1500);if(fallbackTab)fallbackTab.close()}catch(err){if(!fallbackTab)window.location.href=url;}};viewer.hidden=false;document.body.classList.add("viewer-open")}
function attachProductImageTools(card,p){const img=card.querySelector(".product-photo");const art=card.querySelector(".product-art");if(!img||!art)return;img.tabIndex=0;img.setAttribute("role","button");img.setAttribute("aria-label","Zoom "+p.label+" product image");img.title="Tap to zoom";img.addEventListener("click",()=>openProductImage(p.src,p.label));img.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();openProductImage(p.src,p.label)}});const actions=document.createElement("div");actions.className="product-image-actions";actions.innerHTML='<button type="button" class="image-action-zoom" aria-label="Zoom image" title="Zoom image">⌕</button><button type="button" class="image-action-download" aria-label="Download product image" title="Download product image">⬇</button>';actions.querySelector(".image-action-zoom").addEventListener("click",()=>openProductImage(p.src,p.label));actions.querySelector(".image-action-download").addEventListener("click",()=>openProductImage(p.src,p.label));art.appendChild(actions)}

function render(){const matches=products.filter(p=>(p.label+" "+p.category+" "+p.key).toLowerCase().includes(query.toLowerCase()));const shown=matches.slice(0,shownCount);grid.innerHTML="";
shown.forEach(p=>{const card=document.createElement("article");card.className="product-card";card.innerHTML='<div class="product-art"><span class="new-badge">'+p.category+'</span><img class="product-photo" src="'+p.src+'" alt="'+p.label+' football jersey design" loading="lazy"><span class="photo-fallback" aria-hidden="true">👕</span></div><div class="product-info"><div class="product-name">'+p.label+'</div><div class="price">'+money(p)+'</div><button class="order-button" type="button">☏ Click to Order</button></div>';const img=card.querySelector(".product-photo"),fallback=card.querySelector(".photo-fallback");fallback.hidden=true;attachProductImageTools(card,p);img.addEventListener("error",()=>{img.hidden=true;fallback.hidden=false;});card.querySelector(".order-button").addEventListener("click",()=>{const msg="Hi IT WORLD JERSEY, I would like to order/inquire about "+p.label+" ("+p.category+"). Image: "+p.src+". Please share price and availability.";window.open("https://wa.me/"+WA+"?text="+encodeURIComponent(msg),"_blank","noopener");});grid.appendChild(card);});
empty.hidden=matches.length>0;count.textContent=shown.length+" of "+matches.length+" designs";load.hidden=shown.length>=matches.length;}
render();const input=document.getElementById("searchInput");document.getElementById("searchButton").addEventListener("click",()=>{query=input.value.trim();shownCount=24;render()});input.addEventListener("keydown",e=>{if(e.key==="Enter"){query=input.value.trim();shownCount=24;render()}});document.getElementById("menuToggle").addEventListener("click",()=>document.getElementById("mainNav").classList.toggle("open"));
let slide=0;const dots=[...document.querySelectorAll("#slideDots button")],hero=document.getElementById("heroArt"),themes=[["#1c5276","#ff1738"],["#254d38","#e2b83b"],["#17233f","#4da5e8"],["#48202a","#ff5a73"],["#1b293b","#c7f36b"]],banners=products.filter(p=>!p.variant).slice(0,5);
function setSlide(n){slide=(n+banners.length)%banners.length;hero.classList.add("has-photo");hero.style.backgroundImage="linear-gradient(90deg,#05070b66,#05070b22),url('"+banners[slide].src+"')";hero.style.backgroundSize="cover";hero.style.backgroundPosition="center";hero.style.backgroundColor=themes[slide][0];dots.forEach((d,i)=>d.classList.toggle("selected",i===slide));}
document.getElementById("prevSlide").addEventListener("click",()=>setSlide(slide-1));document.getElementById("nextSlide").addEventListener("click",()=>setSlide(slide+1));dots.forEach((d,i)=>d.addEventListener("click",()=>setSlide(i)));setSlide(0);window.setInterval(()=>setSlide(slide+1),5000);load.addEventListener("click",()=>{shownCount+=24;render()});
